    cS += Math.sin(d*f*1.3-t*sp*0.8+0.7)*w*0.5;
  }
  const n = src.length;
  const act=aS/n, inh=iS/n, cross=cS/n;
  const bg = (Math.sin(sx*0.038+sy*0.024+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
