      if (d < md) { md2 = md; md = d; } else if (d < md2) { md2 = d; }
    }
    return Math.tanh((md2-md)*0.15-0.5)*0.2;
  })();
  const blend = coupled*0.6 + cell*0.2 + voronoi*0.15 + spiral*0.05;
  const v = blend*0.5+0.5;
